import type { Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/**
 * Whether the actor may see the project at all. Org and public projects are
 * visible to anyone in the org; a `private` one also needs a role that may
 * read private projects (admin and above, or platform staff), to be its lead,
 * or to be an explicit project member. Membership and lead changes apply on
 * the next call — nothing here is cached.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (actor.orgId !== project.orgId) return false;
  if (project.visibility !== "private") return true;
  if (can(actor, "project:read_private", projectResource(project))) return true;
  if (project.leadId === actor.userId) return true;

  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/**
 * Hides a project the actor may not see. The error is `NotFoundError`, not a
 * permission denial, so a private project looks exactly like one that does
 * not exist.
 */
export async function assertProjectVisible(
  actor: Actor,
  project: Project,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Project", project.id);
  }
}

/**
 * Issues inherit the visibility of their project. A hidden issue is reported
 * as missing under its own id, which is what the caller looked up.
 */
export async function assertIssueVisible(
  actor: Actor,
  issue: Issue,
): Promise<void> {
  const project = requireFound(
    await projectRepo.findProjectById(issue.orgId, issue.projectId),
    "Project",
    issue.projectId,
  );
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Issue", issue.id);
  }
}

/** The listing scope for `actor`: whether they may see private projects at all. */
export function projectViewerFor(actor: Actor): ProjectViewer {
  return {
    orgId: actor.orgId,
    userId: actor.userId,
    seesPrivate: can(actor, "project:read_private", orgResource(actor.orgId)),
  };
}
